choice.source:
// A row of options of which one is chosen: seasons, stages, modes, steps of a story. It
// marks its own choice and sends "change" with the chosen option and its index.
const d = api.data,
  t = api.theme;
const options = (d.options || []).map(String);
const color = d.color || t.accent || "#d97757";
let chosen = Math.max(0, options.indexOf(String(d.value ?? options[0])));
const root = api.html(`<style>
  .c{display:flex;align-items:center;justify-content:center;gap:6px;height:100%;flex-wrap:wrap;font-size:${Number(d.size ?? 15)}px}
  button{border:1.5px solid ${color};background:transparent;color:${color};border-radius:999px;padding:.35em 1em;cursor:pointer;font:inherit}
  button[aria-pressed=true]{background:${color};color:${t.paper || "#fff"}}
</style><div class="c" data-interactive></div>`);
const row = root.querySelector(".c");
const buttons = options.map((label, i) => {
  const b = document.createElement("button");
  b.textContent = label;
  b.dataset.option = String(i);
  b.addEventListener("click", () => {
    chosen = i;
    buttons.forEach((x, j) =>
      x.setAttribute("aria-pressed", String(j === chosen)),
    );
    void api.emit("change", { option: label, index: i });
  });
  row.append(b);
  return b;
});
buttons.forEach((x, j) => x.setAttribute("aria-pressed", String(j === chosen)));
return root;

ground-shadow.source:
// A soft contact shadow that sets an object on the ground instead of floating it. Place it
// as a flat module just under the object's base, about as wide as the object.
const d = api.data,
  t = api.theme;
const W = api.width,
  H = api.height;
const o = Number(d.opacity ?? 0.22);
const color = d.color || t.ink || "#000";
const id = "g" + Math.random().toString(36).slice(2, 8);
return api.svg(`<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}">
  <defs><radialGradient id="${id}"><stop offset="0" stop-color="${color}" stop-opacity="${o}"/><stop offset="0.55" stop-color="${color}" stop-opacity="${o * 0.5}"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></radialGradient></defs>
  <ellipse cx="${W / 2}" cy="${H / 2}" rx="${W / 2}" ry="${H / 2}" fill="url(#${id})"/>
</svg>`);

picture.source:
// A library picture set on the page: fitted by its visible content and resting on the
// bottom of the module, optionally grounded by a soft shadow, with its caption directly
// under the picture rather than under the module.
const d = api.data,
  t = api.theme;
const W = api.width,
  H = api.height;
const info = api.materials[d.material];
if (!info) throw Error(`素材 ${d.material} 不在作品中`);
const size = Number(d.captionSize ?? 15);
const caption = d.caption ? String(d.caption) : "";
const below = caption ? size * 1.8 : 0;
const shade = d.shadow ? Math.max(6, H * 0.05) : 0;
const room = H - below - shade * 0.6;
const k = (d.fit === "cover" ? Math.max : Math.min)(
  W / info.width,
  room / info.height,
);
const pw = Math.min(W, info.width * k),
  ph = Math.min(room, info.height * k);
const top = room - ph;
const root = api.html(
  `<div style="position:relative;width:${W}px;height:${H}px"></div>`,
).firstElementChild;
if (shade) {
  const s = document.createElement("div");
  s.style.cssText = `position:absolute;left:${(W - pw * 0.8) / 2}px;width:${pw * 0.8}px;top:${room - shade * 0.55}px;height:${shade}px;border-radius:50%;background:radial-gradient(closest-side,rgba(0,0,0,.2),rgba(0,0,0,.07) 60%,transparent)`;
  root.append(s);
}
const picture = api.material(d.material, {
  width: pw,
  height: ph,
  fit: d.fit ?? "contain",
  ...(d.color ? { color: d.color } : {}),
});
picture.style.position = "absolute";
picture.style.left = (W - pw) / 2 + "px";
picture.style.top = top + "px";
root.append(picture);
if (caption) {
  const c = document.createElement("div");
  c.textContent = caption;
  c.style.cssText = `position:absolute;left:-20%;right:-20%;top:${room + shade * 0.4 + size * 0.3}px;text-align:center;font-size:${size}px;line-height:1.3;color:${d.color || t.ink || "#222"};white-space:nowrap`;
  root.append(c);
}
return root;

label.source:
// A short label in the work's type with a paper-coloured halo, so it stays legible over
// pictures and lines. Lines break at "\n"; an optional note sits underneath, smaller.
const d = api.data,
  t = api.theme;
const W = api.width,
  H = api.height;
const size = Number(d.size ?? 16);
const align = d.align ?? "center";
const x = align === "start" ? 0 : align === "end" ? W : W / 2;
const anchor = align === "center" ? "middle" : align;
const esc = (s) =>
  String(s).replace(
    /[&<>"]/g,
    (ch) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[ch],
  );
const lines = String(d.text ?? "").split("\n");
const note = d.note ? String(d.note).split("\n") : [];
const noteSize = size * 0.78;
const total = lines.length * size * 1.25 + note.length * noteSize * 1.3;
let y = (H - total) / 2 + size * 0.95;
const halo =
  d.halo === false
    ? ""
    : `paint-order="stroke" stroke="${t.paper || "#fff"}" stroke-width="${Math.max(3, size / 4)}" stroke-linejoin="round"`;
const rows = [];
for (const line of lines) {
  rows.push(
    `<text x="${x}" y="${y}" text-anchor="${anchor}" font-size="${size}" font-weight="${d.weight ?? 500}" fill="${d.color || t.ink || "#222"}" ${halo}>${esc(line)}</text>`,
  );
  y += size * 1.25;
}
for (const line of note) {
  rows.push(
    `<text x="${x}" y="${y}" text-anchor="${anchor}" font-size="${noteSize}" fill="${d.noteColor || t.muted || "#777"}" ${halo}>${esc(line)}</text>`,
  );
  y += noteSize * 1.3;
}
return api.svg(
  `<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" style="overflow:visible" font-family="${esc(t.font || "system-ui")}">${rows.join("")}</svg>`,
);

root.interaction:
// 选一种画风：苹果原地换装，名字和特点跟着变
const looks = [{"material":"apple","name":"Coloured pencil","note":"Colour laid on stroke by stroke"},{"material":"apple-crayon","name":"Crayon","note":"Thick lines and bold colour, like a child's"},{"material":"apple-watercolor","name":"Watercolour","note":"Washes that bleed into soft edges"},{"material":"apple-ink-wash","name":"Ink wash","note":"Graded ink and a lot of empty paper"},{"material":"apple-textbook","name":"Textbook","note":"Even lines, quiet colour, clarity first"},{"material":"apple-realistic","name":"Realistic","note":"Light and texture like a photograph"},{"material":"apple-flat","name":"Flat","note":"Geometric shapes, no outlines"}];
api.on("styles", "change", async ({ index }) => {
  const look = looks[index];
  await api.set("apple", { material: look.material });
  await api.set("caption", { text: look.name, note: look.note });
});
